mapper.select:
SELECT id, task_type, biz_id, action_time, next_fire_time,
       status, retry_count, created_at, updated_at
FROM timeout_task
WHERE task_type = #{taskType}
  AND biz_id = #{bizId}

mapper.update:
UPDATE timeout_task
SET status     = 'CANCELED',
    updated_at = NOW()
WHERE task_type = #{taskType}
  AND biz_id = #{bizId}
  AND status IN ('WAITING', 'RETRYING')

UPDATE timeout_task
SET status     = 'CANCELED',
    updated_at = NOW()
WHERE task_type = #{taskType}
  AND biz_id = #{bizId}
  AND status = 'FAILED'
